<?php
require_once __DIR__.'/includes/functions.php';$message='If that account exists and email is configured, password reset instructions will arrive shortly.';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);if($email){$s=db()->prepare('SELECT id FROM customer_accounts WHERE email=?');$s->execute([$email]);$aid=$s->fetchColumn();$base=rtrim((string)getenv('COLLINS_M_BASE_URL'),'/');$from=(string)getenv('COLLINS_M_FROM_EMAIL');if($aid&&$base&&filter_var($from,FILTER_VALIDATE_EMAIL)){try{$token=bin2hex(random_bytes(32));db()->prepare('INSERT INTO customer_password_resets(account_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$aid,hash('sha256',$token)]);$url=$base.'/reset-password.php?token='.rawurlencode($token);$headers='From: Collins M <'.$from.'>'."\r\n".'Content-Type: text/plain; charset=UTF-8';@mail($email,'Reset your Collins M password',"Reset your password within 30 minutes using this link:\n\n".$url."\n\nIf you did not request this, ignore this email.",$headers);}catch(Throwable $e){error_log('Password reset email could not be queued.');}}}flash('success',$message);header('Location: forgot-password.php');exit;}$page_title='Reset password';require 'includes/header.php';?><section class="section"><div class="container auth-card"><p class="eyebrow">Account recovery</p><h1>Forgot password?</h1><p><?=e($message)?></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Email<input required type="email" name="email"></label><button class="button primary">Send reset instructions</button></form></div></section><?php require 'includes/footer.php';
